components.css:
.ds-btn-primary {
  display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem;
  padding: 0.75rem 1.5rem; border: none; border-radius: 6px;
  background: #FFB900; color: #0A0A0A;
  font-family: var(--font-archivo, system-ui, sans-serif); font-size: 0.875rem; font-weight: 600;
  line-height: 1.25rem; letter-spacing: -0.02em;
  cursor: pointer;
  box-shadow: 0 0 20px rgba(255,185,0,0.35);
  transition: background 300ms cubic-bezier(0, 0, 0.2, 1), box-shadow 300ms cubic-bezier(0, 0, 0.2, 1), transform 300ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-btn-primary:hover { background: #E0A800; box-shadow: 0 0 30px rgba(255,185,0,0.55); transform: translateY(-1px); }
.ds-btn-primary:active { transform: scale(0.95); }
.ds-btn-primary:focus-visible { outline: none; box-shadow: 0 0 0 2px #0A0A0A, 0 0 0 4px #FFB900, 0 0 30px rgba(255,185,0,0.55); }
.ds-btn-primary:disabled { opacity: 0.5; pointer-events: none; }

.ds-btn-ghost {
  display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem;
  padding: 0.75rem 1.5rem; border: 1px solid #2E2E2E; border-radius: 6px;
  background: transparent; color: #F0F0F0;
  font-family: var(--font-archivo, system-ui, sans-serif); font-size: 0.875rem; font-weight: 500;
  line-height: 1.25rem; letter-spacing: -0.02em;
  cursor: pointer;
  transition: background 300ms cubic-bezier(0, 0, 0.2, 1), border-color 300ms cubic-bezier(0, 0, 0.2, 1), color 300ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-btn-ghost:hover { background: #141414; border-color: #FFB900; color: #FFB900; }
.ds-btn-ghost:focus-visible { outline: none; box-shadow: 0 0 0 2px #0A0A0A, 0 0 0 4px #FFB900; }
.ds-btn-ghost:disabled { opacity: 0.5; pointer-events: none; }

.ds-card {
  border-radius: 16px; background: #141414; color: #F0F0F0;
  padding: 1.5rem;
  font-family: var(--font-archivo, system-ui, sans-serif);
  transition: background-color 300ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-card:hover { background: #1F1F1F; }
.ds-card-title { margin: 0 0 1.25rem; font-size: 1.125rem; font-weight: 500; letter-spacing: -0.01em; color: #F0F0F0; }
.ds-card-body { margin: 0; font-size: 0.875rem; line-height: 1.625; color: #9A9A9A; }

.ds-field { font-family: var(--font-archivo, system-ui, sans-serif); }
.ds-field-label { display: block; margin-bottom: 0.375rem; font-size: 0.875rem; font-weight: 500; letter-spacing: -0.01em; color: #F0F0F0; }
.ds-field-wrap { position: relative; }
.ds-field-wrap svg { position: absolute; left: 0.75rem; top: 50%; transform: translateY(-50%); color: #9A9A9A; }
.ds-input {
  display: block; width: 100%; padding: 0.75rem 1rem 0.75rem 2.5rem;
  border: 1px solid #2E2E2E; border-radius: 6px;
  background: transparent; color: #F0F0F0; caret-color: #FFB900;
  font-family: var(--font-archivo, system-ui, sans-serif); font-size: 0.875rem; line-height: 1.25rem;
  transition: border-color 200ms cubic-bezier(0, 0, 0.2, 1), box-shadow 200ms cubic-bezier(0, 0, 0.2, 1);
}
.ds-input::placeholder { color: #B5B5B5; }
.ds-input:focus { outline: none; border-color: #FFB900; box-shadow: 0 0 0 1px #FFB900; }
.ds-input:focus-visible { outline: none; border-color: #FFB900; box-shadow: 0 0 0 1px #FFB900, 0 0 0 3px #0A0A0A, 0 0 0 5px #FFB900; }
.ds-input:disabled { opacity: 0.5; }

.ds-nav { position: sticky; top: 0; z-index: 50; background: rgba(10,10,10,0.8); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); box-shadow: 0 8px 30px rgba(0,0,0,0.55); font-family: var(--font-archivo, system-ui, sans-serif); }
.ds-nav-inner { max-width: 64rem; margin: 0 auto; padding: 0 1rem; height: 4rem; display: flex; align-items: center; justify-content: space-between; }
.ds-brand { display: inline-flex; align-items: center; gap: 0.5rem; text-decoration: none; }
.ds-brand-mark { width: 1.75rem; height: 1.75rem; border-radius: 6px; background: #FFB900; color: #0A0A0A; display: inline-flex; align-items: center; justify-content: center; box-shadow: 0 0 15px rgba(255,185,0,0.4); transition: transform 300ms cubic-bezier(0, 0, 0.2, 1); }
.ds-brand:hover .ds-brand-mark { transform: scale(1.05); }
.ds-brand-name { font-size: 1.25rem; font-weight: 700; letter-spacing: -0.02em; color: #F0F0F0; transition: color 300ms cubic-bezier(0, 0, 0.2, 1); }
.ds-brand:hover .ds-brand-name { color: #FFB900; }
.ds-nav-links { display: flex; align-items: center; gap: 2rem; }
.ds-nav-link { display: inline-flex; align-items: center; gap: 0.5rem; font-size: 0.875rem; font-weight: 500; color: #9A9A9A; text-decoration: none; transition: color 300ms cubic-bezier(0, 0, 0.2, 1); }
.ds-nav-link:hover { color: #F0F0F0; }
.ds-nav-auth { display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.375rem 1rem; border: 1px solid #2E2E2E; border-radius: 6px; background: transparent; color: #F0F0F0; font-family: var(--font-archivo, system-ui, sans-serif); font-size: 0.875rem; font-weight: 500; text-decoration: none; transition: background 300ms cubic-bezier(0, 0, 0.2, 1), color 300ms cubic-bezier(0, 0, 0.2, 1), border-color 300ms cubic-bezier(0, 0, 0.2, 1); }
.ds-nav-auth:hover { background: #141414; border-color: #FFB900; color: #FFB900; }
.ds-nav-auth:focus-visible { outline: none; box-shadow: 0 0 0 2px #0A0A0A, 0 0 0 4px #FFB900; }
@media (max-width: 767px) { .ds-nav-links { display: none; } }
.ds-nav-signout { display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.375rem 0.75rem; border: 1px solid transparent; border-radius: 6px; background: #141414; color: #9A9A9A; font-family: var(--font-archivo, system-ui, sans-serif); font-size: 0.875rem; cursor: pointer; transition: background 300ms cubic-bezier(0, 0, 0.2, 1), color 300ms cubic-bezier(0, 0, 0.2, 1); }
.ds-nav-signout:hover { background: #1F1F1F; color: #F0F0F0; }

.ds-pill { display: inline-flex; align-items: center; gap: 0.25rem; padding: 0.125rem 0.625rem; border-radius: 9999px; background: #141414; color: #B5B5B5; font-family: var(--font-archivo, system-ui, sans-serif); font-size: 0.75rem; font-weight: 500; }
.ds-pill-dot { width: 0.375rem; height: 0.375rem; border-radius: 9999px; background: #9A9A9A; }
.ds-pill--live { color: #4ADE80; } .ds-pill--live .ds-pill-dot { background: #4ADE80; }
.ds-pill--building { color: #FFB900; } .ds-pill--building .ds-pill-dot { background: #FFB900; animation: ds-pulse 1.6s ease-in-out infinite; }
.ds-pill--warning { color: #FACC15; } .ds-pill--warning .ds-pill-dot { background: #FACC15; }
@keyframes ds-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }

.ds-link { color: #FFB900; text-decoration: underline; text-underline-offset: 2px; text-decoration-color: rgba(255,185,0,0.3); font-family: var(--font-archivo, system-ui, sans-serif); font-size: 0.875rem; transition: color 200ms cubic-bezier(0, 0, 0.2, 1), text-decoration-color 200ms cubic-bezier(0, 0, 0.2, 1); }
.ds-link:hover { color: #FFD24D; text-decoration-color: #FFB900; }
.ds-link:focus-visible { outline: none; box-shadow: 0 0 0 2px #0A0A0A, 0 0 0 4px #FFB900; border-radius: 2px; }

.ds-dust-field { position: relative; overflow: hidden; background: #0A0A0A; border-radius: 16px; font-family: var(--font-archivo, system-ui, sans-serif); }
.ds-dust-layer { position: absolute; inset: -25%; background-repeat: repeat; pointer-events: none; }
.ds-dust-far { --dust-drift: 78px; background-image: radial-gradient(circle, rgba(240,240,240,0.14) 1px, transparent 1.1px); background-size: 26px 26px; animation: ds-dust-drift 96s linear infinite; }
.ds-dust-mid { --dust-drift: 88px; background-image: radial-gradient(circle, rgba(240,240,240,0.28) 1.6px, transparent 1.7px); background-size: 44px 44px; animation: ds-dust-drift 54s linear infinite; }
.ds-dust-near { --dust-drift: 78px; background-image: radial-gradient(circle, rgba(240,240,240,0.5) 2.6px, transparent 2.7px); background-size: 78px 78px; animation: ds-dust-drift 31s linear infinite; }
.ds-dust-content { position: relative; padding: 3rem 2rem; }
.ds-dust-title { margin: 0; max-width: 18ch; font-size: 3rem; font-weight: 700; line-height: 1.05; letter-spacing: -0.03em; color: #F0F0F0; }
@keyframes ds-dust-drift { from { transform: translate3d(0, 0, 0); } to { transform: translate3d(calc(-1 * var(--dust-drift)), calc(-1 * var(--dust-drift)), 0); } }
@media (prefers-reduced-motion: reduce) { .ds-dust-layer { animation: none; } }
